if (points.empty()) {
    return BoundingBox2();
}

// Find the initial bounding box using axis-aligned bounding box
BoundingBox2 bb;
bb.min() = points[0];
bb.max() = points[0];
for (size_t i = 1; i < points.size(); ++i) {
    bb.min() = bb.min().min(points[i]);
    bb.max() = bb.max().max(points[i]);
}

// If we have less than 3 points, the axis-aligned box is optimal
if (points.size() < 3) {
    return bb;
}

// Rotating Calipers algorithm for minimum area bounding box
// Step 1: Compute convex hull
std::vector<Point2d> hull;
hull = points; // Simplified: in practice, use a convex hull algorithm
// For correctness, we must compute convex hull first
// Since we don't have a convex hull function provided, we assume we can use a simple one
// But the problem doesn't provide one, so we must implement a minimal version

// We'll implement a simple Graham scan for convex hull
if (points.size() <= 1) {
    return bb;
}

// Create a copy and sort by polar angle
std::vector<Point2d> sortedPoints = points;
// Find the point with minimum y (and minimum x if tie)
size_t startIdx = 0;
for (size_t i = 1; i < sortedPoints.size(); ++i) {
    if (sortedPoints[i].y() < sortedPoints[startIdx].y() ||
        (sortedPoints[i].y() == sortedPoints[startIdx].y() && sortedPoints[i].x() < sortedPoints[startIdx].x())) {
        startIdx = i;
    }
}
std::swap(sortedPoints[0], sortedPoints[startIdx]);

// Sort by polar angle with respect to the first point
auto polarCompare = [&](const Point2d& a, const Point2d& b) -> bool {
    // Vector from first point to a and b
    Point2d va = a - sortedPoints[0];
    Point2d vb = b - sortedPoints[0];
    double cross = va.x() * vb.y() - va.y() * vb.x();
    if (cross > 0) return true;
    if (cross < 0) return false;
    // Collinear: choose the closer one
    double da = va.lengthSquared();
    double db = vb.lengthSquared();
    return da < db;
};

std::sort(sortedPoints.begin() + 1, sortedPoints.end(), polarCompare);

// Graham scan to build convex hull
hull.clear();
hull.push_back(sortedPoints[0]);
hull.push_back(sortedPoints[1]);

for (size_t i = 2; i < sortedPoints.size(); ++i) {
    while (hull.size() >= 2) {
        Point2d p1 = hull[hull.size() - 2];
        Point2d p2 = hull[hull.size() - 1];
        Point2d p3 = sortedPoints[i];
        // Cross product of (p2-p1) and (p3-p1)
        double cross = (p2.x() - p1.x()) * (p3.y() - p1.y()) - (p2.y() - p1.y()) * (p3.x() - p1.x());
        if (cross > 0) break; // left turn
        hull.pop_back();
    }
    hull.push_back(sortedPoints[i]);
}

// If hull has less than 3 points, use the axis-aligned bounding box
if (hull.size() < 3) {
    return bb;
}

// Step 2: Rotating Calipers
double minArea = std::numeric_limits<double>::max();
BoundingBox2 minBox;

// For each edge of the convex hull
for (size_t i = 0; i < hull.size(); ++i) {
    size_t next = (i + 1) % hull.size();
    Point2d edge = hull[next] - hull[i];
    double edgeLength = edge.length();
    if (edgeLength < 1e-10) continue; // Skip zero-length edges

    // Normalize edge direction
    Point2d edgeDir = edge / edgeLength;
    Point2d normal(-edgeDir.y(), edgeDir.x()); // Perpendicular unit vector

    // Project all points onto edgeDir and normal
    double minProjEdge = std::numeric_limits<double>::max();
    double maxProjEdge = -std::numeric_limits<double>::max();
    double minProjNorm = std::numeric_limits<double>::max();
    double maxProjNorm = -std::numeric_limits<double>::max();

    for (const Point2d& p : hull) {
        double projEdge = p.dot(edgeDir);
        double projNorm = p.dot(normal);
        minProjEdge = std::min(minProjEdge, projEdge);
        maxProjEdge = std::max(maxProjEdge, projEdge);
        minProjNorm = std::min(minProjNorm, projNorm);
        maxProjNorm = std::max(maxProjNorm, projNorm);
    }

    double width = maxProjEdge - minProjEdge;
    double height = maxProjNorm - minProjNorm;
    double area = width * height;

    if (area < minArea) {
        minArea = area;
        // Construct the bounding box corners
        Point2d center = hull[i] + edgeDir * (minProjEdge + width / 2.0) + normal * (minProjNorm + height / 2.0);
        Point2d corner1 = center + edgeDir * (width / 2.0) + normal * (height / 2.0);
        Point2d corner2 = center + edgeDir * (width / 2.0) - normal * (height / 2.0);
        Point2d corner3 = center - edgeDir * (width / 2.0) - normal * (height / 2.0);
        Point2d corner4 = center - edgeDir * (width / 2.0) + normal * (height / 2.0);

        // Find min and max of the rotated box
        Point2d minCorner(corner1.x(), corner1.y());
        Point2d maxCorner(corner1.x(), corner1.y());
        for (const Point2d& c : {corner2, corner3, corner4}) {
            minCorner = minCorner.min(c);
            maxCorner = maxCorner.max(c);
        }
        minBox.set(minCorner, maxCorner);
    }
}

// Return the minimum area bounding box found
return minBox;

